"""Five new application questions per lesson; added to lesson practice only.

Columns: prompt || correct option || three distractors || explanation.
These questions complement, rather than copy, the original 60 per course.
"""

def questions(source):
    result = []
    for line in source.strip().splitlines():
        if not line.strip():
            continue
        prompt, answer, b, c, d, explanation = [part.strip() for part in line.split(' || ')]
        result.append(dict(prompt=prompt, options=[answer, b, c, d], correct=0,
                           explanation=explanation, difficulty='medium'))
    assert len(result) == 5
    return result


